import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.CqGPl1zp.js";const c=JSON.parse('{"title":"【模型接入】Grok","description":"","frontmatter":{},"headers":[],"relativePath":"ai/grok.md","filePath":"ai/grok.md","lastUpdated":null}'),o={name:"ai/grok.md"};function r(l,a,d,n,h,p){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="【模型接入】grok" tabindex="-1">【模型接入】Grok <a class="header-anchor" href="#【模型接入】grok" aria-label="Permalink to &quot;【模型接入】Grok&quot;">​</a></h1><p>项目基于 Spring AI + 自己实现的 <code>models/grok</code>，实现 <a href="https://x.ai/" target="_blank" rel="noreferrer">xAI Grok</a> 的接入，底层复用兼容 OpenAI 协议的客户端：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td>grok-4.3、grok-4-fast 等</td><td>GrokChatModel</td></tr><tr><td>AI 绘画</td><td>暂未接入</td><td>暂未接入</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>Grok 是 xAI 提供的非开源模型，需要在 xAI 控制台申请 API Key，然后通过兼容 OpenAI 协议的客户端接入。</p><p>① 在 <a href="https://console.x.ai/" target="_blank" rel="noreferrer">xAI Console</a> 上，注册一个账号。</p><p>② 在 <a href="https://console.x.ai/team/api-keys" target="_blank" rel="noreferrer">API Keys</a> 页面，创建一个 API Key 密钥。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置，字段可以按下面填写：</p><ul><li>名称：<code>Grok</code></li><li>所属平台：<code>Grok</code></li><li>API 密钥：填写上一步创建的 xAI API Key</li><li>自定义 API URL：不填写，项目默认使用 xAI 官方地址</li></ul><p>友情提示：</p><p>Grok 官方 API 在部分网络环境下可能连接不上。如果调用失败，可以先检查网络连通性，或者改用可访问的 OpenAI 兼容中转地址。</p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型，字段可以按下面填写：</p><ul><li>模型名称：<code>grok-4.3</code></li><li>所属平台：<code>Grok</code></li><li>模型类型：<code>聊天</code></li><li>模型标识：<code>grok-4.3</code></li><li>API 密钥：选择前面配置的 Grok 密钥</li><li>回复数 Token 数：<code>8192</code></li></ul><p>不同模型的 <code>max_tokens</code>（回复数 Token 数）上限不同，可以参考下表填写：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>grok-4.3</code></td><td>8192</td></tr><tr><td><code>grok-4-fast</code></td><td>8192</td></tr></tbody></table><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>TODO 等待 Grok ImageModel 客户端！</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 GrokChatModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.grok</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    grok</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Grok</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${GROK_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">grok-4.3</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，GrokChatModelTests 里有对应的测试用例，可以参考。</p>`,29)])])}const g=e(o,[["render",r]]);export{c as __pageData,g as default};
